// Generated by esquadro: do not edit. The notices of who signs in: a bell
// in the header with how many are unread, the last ones in a popover, and
// a page with all of them.
import { keepPreviousData, useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import { Link, useNavigate } from "@tanstack/react-router"
import { Bell, BellOff, Check, CheckCheck, ChevronLeft, ChevronRight, Trash2 } from "lucide-react"
import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { Skeleton } from "@/components/ui/skeleton"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { cn } from "@/lib/utils"
import { api } from "../api.ts"
import { notifications } from "../config.ts"
import { seen } from "./accounts-admin.tsx"
import { describe } from "./errors.ts"
import { t } from "./i18n.ts"
import { PageHeader } from "./page.tsx"
import { ErrorState, StateView } from "./states.tsx"
import { toast } from "./toast.tsx"

interface Notice {
  id: string
  title: string
  text: string
  link: string
  created_at: string
  read_at: string | null
}

interface NoticePage {
  items: Notice[]
  page: number
  total_pages: number
  unread: number
}

interface NoticesApi {
  list(query: { unread?: boolean; page?: number; per_page?: number }, o?: { signal?: AbortSignal }): Promise<NoticePage>
  count(o?: { signal?: AbortSignal }): Promise<{ unread: number }>
  read(id: string): Promise<void>
  readAll(): Promise<void>
  remove(id: string): Promise<void>
}

const notices = () => (api as unknown as { notifications: NoticesApi }).notifications

/** Marking read, all of them, and taking off: then the bell and the lists again. */
function useNoticeActions() {
  const queryClient = useQueryClient()
  const refresh = () => queryClient.invalidateQueries({ queryKey: ["notifications"] })
  const run = useMutation({
    mutationFn: (f: () => Promise<void>) => f(),
    onSuccess: refresh,
    onError: (e) => toast(describe(e), "error"),
  })
  return {
    read: (n: Notice) => (n.read_at ? Promise.resolve() : run.mutateAsync(() => notices().read(n.id))),
    readAll: () => run.mutate(() => notices().readAll()),
    remove: (n: Notice) => run.mutate(() => notices().remove(n.id)),
    busy: run.isPending,
  }
}

/** A notice in a list: unread ones marked; a click leads where it says. */
function NoticeRow({ n, onOpen, onRead, onRemove }: { n: Notice; onOpen: () => void; onRead: () => void; onRemove?: () => void }) {
  return (
    <div className={cn("group flex items-start gap-3 rounded-lg px-3 py-2.5 hover:bg-muted", !n.read_at && "bg-primary/5")}>
      <span className={cn("mt-1.5 size-2 shrink-0 rounded-full", n.read_at ? "bg-transparent" : "bg-primary")} />
      <button type="button" className="min-w-0 flex-1 text-left" onClick={onOpen}>
        <p className={cn("text-sm text-foreground", !n.read_at && "font-semibold")}>{n.title}</p>
        {n.text && <p className="line-clamp-2 text-xs text-muted-foreground">{n.text}</p>}
        <p className="mt-0.5 text-xs text-muted-foreground">{seen(n.created_at)}</p>
      </button>
      <div className="flex shrink-0 items-center gap-0.5">
        {!n.read_at && (
          <Button variant="ghost" size="icon-sm" className="text-muted-foreground hover:text-primary" aria-label={t("markRead")} title={t("markRead")} onClick={onRead}>
            <Check />
          </Button>
        )}
        {onRemove && (
          <Button
            variant="ghost"
            size="icon-sm"
            className="text-muted-foreground opacity-0 group-hover:opacity-100 hover:text-destructive focus-visible:opacity-100"
            aria-label={t("delete")}
            title={t("delete")}
            onClick={onRemove}
          >
            <Trash2 />
          </Button>
        )}
      </div>
    </div>
  )
}

/** The bell of the header: how many are unread, the last ones in a popover. */
export function NotificationBell() {
  const navigate = useNavigate()
  const [open, setOpen] = useState(false)
  const [only, setOnly] = useState<"all" | "unread">("all")
  const actions = useNoticeActions()
  const poll = (notifications?.poll ?? 0) * 1000
  const count = useQuery({
    queryKey: ["notifications", "count"],
    queryFn: ({ signal }) => notices().count({ signal }),
    refetchInterval: poll > 0 ? poll : false,
    refetchOnWindowFocus: true,
  })
  const list = useQuery({
    queryKey: ["notifications", "bell", only],
    queryFn: ({ signal }) => notices().list({ unread: only === "unread" || undefined, per_page: notifications?.size ?? 10 }, { signal }),
    enabled: open,
  })
  const unread = count.data?.unread ?? 0
  const openNotice = async (n: Notice) => {
    setOpen(false)
    await actions.read(n)
    if (n.link) navigate({ to: n.link as never })
  }
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant="ghost" size="icon" className="relative" aria-label={unread ? t("notificationsUnread", { count: unread }) : t("notifications")}>
          <Bell />
          {unread > 0 && (
            <span className="absolute top-1 right-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-destructive px-1 text-[10px] font-bold text-white tabular-nums">
              {unread > 9 ? "9+" : unread}
            </span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-96 p-0">
        <div className="flex items-center justify-between gap-2 border-b border-border px-4 py-3">
          <p className="font-bold">{t("notifications")}</p>
          <Button variant="ghost" size="sm" disabled={unread === 0 || actions.busy} onClick={actions.readAll}>
            <CheckCheck /> {t("markAllRead")}
          </Button>
        </div>
        <Tabs value={only} onValueChange={(v) => setOnly(v as "all" | "unread")} className="px-4 pt-2">
          <TabsList variant="line">
            <TabsTrigger value="all">{t("all")}</TabsTrigger>
            <TabsTrigger value="unread">
              {t("unread")}
              {unread > 0 && <span className="ml-1 rounded-full bg-primary/10 px-1.5 text-xs text-primary tabular-nums">{unread}</span>}
            </TabsTrigger>
          </TabsList>
        </Tabs>
        <div className="max-h-96 overflow-y-auto p-2">
          {list.isPending && [0, 1, 2].map((i) => <Skeleton key={i} className="m-2 h-12" />)}
          {list.isError && <p className="p-4 text-sm text-destructive">{describe(list.error)}</p>}
          {list.data?.items.length === 0 && (
            <div className="flex flex-col items-center gap-2 py-10 text-center text-sm text-muted-foreground">
              <BellOff className="size-6" />
              <p className="font-semibold text-foreground">{only === "unread" ? t("noUnreadNotifications") : t("noNotifications")}</p>
              <p className="max-w-60 text-xs">{only === "unread" ? t("noUnreadNotificationsHint") : t("noNotificationsHint")}</p>
            </div>
          )}
          {list.data?.items.map((n) => (
            <NoticeRow key={n.id} n={n} onOpen={() => openNotice(n)} onRead={() => void actions.read(n)} />
          ))}
        </div>
        <div className="border-t border-border p-2">
          <Button variant="ghost" className="w-full" asChild onClick={() => setOpen(false)}>
            <Link to={"/notifications" as never}>{t("seeAllNotifications")}</Link>
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  )
}

/** Every notice, a page at a time, the unread ones apart. */
export function NotificationsPage() {
  const navigate = useNavigate()
  const [page, setPage] = useState(1)
  const [only, setOnly] = useState<"all" | "unread">("all")
  const actions = useNoticeActions()
  const list = useQuery({
    queryKey: ["notifications", "page", only, page],
    queryFn: ({ signal }) => notices().list({ unread: only === "unread" || undefined, page, per_page: 20 }, { signal }),
    placeholderData: keepPreviousData,
  })
  return (
    <div className="flex flex-col gap-4">
      <PageHeader
        title={t("notifications")}
        description={t("notificationsHint")}
        actions={
          <Button variant="outline" disabled={!list.data?.unread || actions.busy} onClick={actions.readAll}>
            <CheckCheck /> {t("markAllRead")}
          </Button>
        }
      />
      <div className="flex flex-col gap-3 rounded-xl border border-border bg-card p-4">
        <Tabs
          value={only}
          onValueChange={(v) => {
            setOnly(v as "all" | "unread")
            setPage(1)
          }}
        >
          <TabsList variant="line">
            <TabsTrigger value="all">{t("all")}</TabsTrigger>
            <TabsTrigger value="unread">{t("unread")}</TabsTrigger>
          </TabsList>
        </Tabs>
        {list.isError ? (
          <ErrorState error={list.error} onRetry={() => list.refetch()} />
        ) : list.data?.items.length === 0 ? (
          <StateView
            icon={<BellOff />}
            title={only === "unread" ? t("noUnreadNotifications") : t("noNotifications")}
            description={only === "unread" ? t("noUnreadNotificationsHint") : t("noNotificationsHint")}
          />
        ) : (
          <div className="flex flex-col gap-1">
            {list.isPending && [0, 1, 2, 3].map((i) => <Skeleton key={i} className="h-14" />)}
            {list.data?.items.map((n) => (
              <NoticeRow
                key={n.id}
                n={n}
                onOpen={async () => {
                  await actions.read(n)
                  if (n.link) navigate({ to: n.link as never })
                }}
                onRead={() => void actions.read(n)}
                onRemove={() => actions.remove(n)}
              />
            ))}
          </div>
        )}
        {list.data && list.data.total_pages > 1 && (
          <div className="flex items-center justify-end gap-1 text-sm">
            <Button variant="ghost" size="icon-sm" disabled={page <= 1} aria-label={t("previous")} onClick={() => setPage(page - 1)}>
              <ChevronLeft />
            </Button>
            <span className="px-2 font-semibold tabular-nums">
              {page} / {list.data.total_pages}
            </span>
            <Button variant="ghost" size="icon-sm" disabled={page >= list.data.total_pages} aria-label={t("next")} onClick={() => setPage(page + 1)}>
              <ChevronRight />
            </Button>
          </div>
        )}
      </div>
    </div>
  )
}
